
const b64url = bytes => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
const fromB64url = value => Uint8Array.from(atob(value.replace(/-/g,"+").replace(/_/g,"/").padEnd(Math.ceil(value.length/4)*4,"=")),c=>c.charCodeAt(0));
async function authSchema(db){
 await db.prepare("CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_salt TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL)").run();
 await db.prepare("CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)").run();
}
async function hashPassword(password,salt){
 const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);
 const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:fromB64url(salt),iterations:210000,hash:"SHA-256"},key,256);
 return b64url(bits);
}
async function tokenHash(token){
 const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(token));
 return b64url(digest);
}
function cookieToken(request){
 const cookie=request.headers.get("Cookie")||"";
 const match=cookie.match(/(?:^|;\s*)shadow_session=([A-Za-z0-9_-]+)/);
 return match?match[1]:"";
}
async function currentUser(request,db){
 const token=cookieToken(request);if(!token)return null;
 const hash=await tokenHash(token);const row=await db.prepare("SELECT users.id,users.email FROM sessions JOIN users ON users.id=sessions.user_id WHERE sessions.token_hash=? AND sessions.expires_at>?").bind(hash,new Date().toISOString()).first();
 return row||null;
}
async function createSession(db,userId){
 const bytes=crypto.getRandomValues(new Uint8Array(32));const token=b64url(bytes);const now=new Date();
 const expires=new Date(now.getTime()+30*24*60*60*1000).toISOString();
 await db.prepare("INSERT INTO sessions(token_hash,user_id,expires_at,created_at) VALUES(?,?,?,?)").bind(await tokenHash(token),userId,expires,now.toISOString()).run();
 return token;
}
const sessionCookie=token=>"shadow_session="+token+"; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000";
const clearSessionCookie="shadow_session=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0";

