            const salt=b64url(crypto.getRandomValues(new Uint8Array(16)));const hash=await hashPassword(password,salt);const id=crypto.randomUUID();
            try{await env.DB.prepare("INSERT INTO users(id,email,password_salt,password_hash,created_at) VALUES(?,?,?,?,?)").bind(id,email,salt,hash,new Date().toISOString()).run();}
            catch(e){if(String(e.message||e).toLowerCase().includes("unique"))return err("Is email se account pehle se bana hua hai. Login karo.",409);throw e;}
            const token=await createSession(env.DB,id);
